/**
 * Browser tests for the UI.
 *
 * IMPORTANT: tests marked [stubbed API] replace the /api/detect response INSIDE THE
 * TEST ONLY, so the drawing, slider, toggles, download and flag features can be checked
 * without Roboflow credentials. The production app never uses fake detections.
 * Tests marked [real API] call the real /api/detect route.
 *
 * Synthetic test images are generated by global-setup.ts into tests/e2e/images.
 */
import fs from "node:fs";
import path from "node:path";
import { type Page, type Route, expect, test } from "@playwright/test";

const IMAGES = path.join(__dirname, "images");
const img = (name: string) => path.join(IMAGES, name);

interface StubPrediction {
  x: number;
  y: number;
  width: number;
  height: number;
  confidence: number;
  class: string;
}

async function stubDetect(page: Page, body: unknown, status = 200, onRequest?: (json: { image: string }) => void) {
  await page.route("**/api/detect", async (route: Route) => {
    onRequest?.(route.request().postDataJSON());
    await route.fulfill({ status, contentType: "application/json", body: JSON.stringify(body) });
  });
}

async function upload(page: Page, file: string) {
  await page.getByTestId("file-input").setInputFiles(img(file));
}

async function canvasSize(page: Page) {
  return page.getByTestId("annotated-canvas").evaluate((c: HTMLCanvasElement) => ({ w: c.width, h: c.height }));
}

async function pixel(page: Page, x: number, y: number) {
  return page
    .getByTestId("annotated-canvas")
    .evaluate((c: HTMLCanvasElement, [px, py]) => Array.from(c.getContext("2d")!.getImageData(px, py, 1, 1).data), [x, y]);
}

// small.jpg is 1200x800. Boxes are centre-based.
const PREDICTIONS: StubPrediction[] = [
  { x: 300, y: 400, width: 100, height: 200, confidence: 0.91, class: "person_left_phone" },
  { x: 600, y: 400, width: 100, height: 200, confidence: 0.85, class: "person_left" },
  { x: 800, y: 400, width: 100, height: 200, confidence: 0.55, class: "person_right" },
  { x: 1000, y: 400, width: 100, height: 200, confidence: 0.45, class: "person_right_phone" },
  { x: 150, y: 600, width: 80, height: 150, confidence: 0.2, class: "person_right" },
];

test.beforeEach(async ({ page }) => {
  await page.goto("/");
});

