  await expect(page.getByRole("heading", { level: 1 })).toHaveText("People Counting Assistant (Team 5)");
  await expect(page.getByText("Detect pedestrians, their direction and phone use at zebra crossings")).toBeVisible();
  await expect(page.getByRole("button", { name: "Analyse" })).toBeDisabled();
