test("[real API] disables Analyse while the request runs, then shows a result or a clean error", async ({ page }) => {
  // Works with or without credentials in .env.local: valid ones give a real result,
  // missing or invalid ones must give a clear, non-retryable error.
  await upload(page, "small.jpg");
  const analyse = page.getByRole("button", { name: "Analyse" });
  await expect(analyse).toBeEnabled();
  await analyse.click();
  await expect(page.getByRole("button", { name: "Analysing…" })).toBeDisabled();
  // A real round trip to Roboflow can take several seconds.
  const errorBox = page.getByTestId("error-box");
  const rating = page.getByTestId("rating-label");
  await expect(errorBox.or(rating)).toBeVisible({ timeout: 35_000 });
  if (await errorBox.isVisible()) {
    await expect(errorBox).toContainText(/Roboflow rejected the request|Roboflow settings are missing/);
    await expect(page.getByRole("button", { name: "Try again" })).toHaveCount(0); // not retryable
  } else {
    // The synthetic test image has no people in it.
    await expect(rating).toBeVisible();
  }
});

test("[stubbed API] draws boxes, counts, rating, slider and toggles", async ({ page }) => {
  await stubDetect(page, { predictions: PREDICTIONS, image: { width: 1200, height: 800 }, malformedCount: 0 });
  await upload(page, "small.jpg");
  await page.getByRole("button", { name: "Analyse" }).click();

  // Default 40%: the 0.2 detection is filtered out -> 2 phone users of 4 people = 50% Medium
  await expect(page.getByTestId("rating-summary")).toHaveText("2 of 4 pedestrians using a phone (50%) - Medium");
  await expect(page.getByTestId("count-total")).toHaveText("4");
  await expect(page.getByTestId("count-person_right")).toHaveText("1");
  expect(await canvasSize(page)).toEqual({ w: 1200, h: 800 });

  // Box for person_left_phone: centre (300,400), 100x200 -> left edge x=250. Should be orange.
  const [r, g, b] = await pixel(page, 250, 450);
  expect(r).toBeGreaterThan(200);
  expect(g).toBeGreaterThan(80);
  expect(g).toBeLessThan(150);
  expect(b).toBeLessThan(60);
  // Walker box (person_left) left edge x=550 -> blue
  const [r2, , b2] = await pixel(page, 550, 450);
  expect(b2).toBeGreaterThan(150);
  expect(r2).toBeLessThan(80);

  // Slider to 10%: the 0.2 person_right is counted -> 2 of 5 = 40% Medium
  const slider = page.getByLabel("Minimum confidence");
  await slider.fill("10");
  await expect(page.getByTestId("rating-summary")).toHaveText("2 of 5 pedestrians using a phone (40%) - Medium");

  // Slider to 60%: only 0.91 phone and 0.85 walker remain -> 1 of 2 = 50%
  await slider.fill("60");
  await expect(page.getByTestId("rating-summary")).toHaveText("1 of 2 pedestrians using a phone (50%) - Medium");

  // Slider to 90%: one phone user -> 100% High
  await slider.fill("90");
  await expect(page.getByTestId("rating-summary")).toHaveText("1 of 1 pedestrian using a phone (100%) - High");

  // Keyboard control of slider
  await slider.focus();
  await page.keyboard.press("ArrowRight");
  await expect(page.getByTestId("threshold-value")).toHaveText("91%");
  await slider.fill("95");
  await expect(page.getByTestId("rating-label")).toHaveText("No pedestrians detected");
  await expect(page.getByTestId("all-filtered")).toBeVisible();

  // Back to 40% then hide phone boxes: counts and rating must NOT change, but the orange box disappears
  await slider.fill("40");
  await page.getByRole("checkbox", { name: "person_left_phone" }).uncheck();
  await expect(page.getByTestId("rating-summary")).toHaveText("2 of 4 pedestrians using a phone (50%) - Medium");
  await expect(page.getByTestId("count-person_left_phone")).toHaveText("1");
  const [r3, g3, b3] = await pixel(page, 250, 450);
  const stillOrange = r3 > 200 && g3 > 80 && g3 < 150 && b3 < 60;
  expect(stillOrange).toBe(false);

  // Download PNG reflects the current settings
  const [download] = await Promise.all([
    page.waitForEvent("download"),
    page.getByRole("button", { name: "Download annotated image (PNG)" }).click(),
  ]);
  expect(download.suggestedFilename()).toBe("small-annotated-40pct.png");
  const file = await download.path();
  const bytes = fs.readFileSync(file);
  expect(bytes.subarray(1, 4).toString()).toBe("PNG");
  expect(bytes.readUInt32BE(16)).toBe(1200); // PNG width
  expect(bytes.readUInt32BE(20)).toBeGreaterThan(800); // image + caption strip
});

test("[stubbed API] flags are saved to localStorage and exported as JSON", async ({ page }) => {
  await stubDetect(page, { predictions: PREDICTIONS, image: { width: 1200, height: 800 }, malformedCount: 0 });
  await upload(page, "small.jpg");
  await page.getByRole("button", { name: "Analyse" }).click();
  await page.getByRole("button", { name: "Flag wrong result" }).click();
  await page.getByLabel("What looks wrong? (optional)").fill("Missed a cyclist");
  await page.getByRole("button", { name: "Save flag" }).click();
  await expect(page.getByText("Flag saved in this browser.")).toBeVisible();

  const stored = await page.evaluate(() => JSON.parse(localStorage.getItem("people-counting-assistant.flags.v1")!));
  expect(stored).toHaveLength(1);
  expect(stored[0]).toMatchObject({
    filename: "small.jpg",
    thresholdPercent: 40,
    totalPeople: 4,
    phoneUsers: 2,
    rating: "Medium",
    ratingPercent: 50,
    note: "Missed a cyclist",
  });
  expect(stored[0].counts).toEqual({ person_left: 1, person_right: 1, person_left_phone: 1, person_right_phone: 1 });
  expect(typeof stored[0].timestamp).toBe("string");

  const [download] = await Promise.all([
    page.waitForEvent("download"),
    page.getByRole("button", { name: /Export flags as JSON \(1\)/ }).click(),
  ]);
  const exported = JSON.parse(fs.readFileSync(await download.path(), "utf8"));
  expect(exported.flags[0].note).toBe("Missed a cyclist");

  // Flags survive a reload
  await page.reload();
  await stubDetect(page, { predictions: [], image: null, malformedCount: 0 });
  await upload(page, "small.jpg");
  await page.getByRole("button", { name: "Analyse" }).click();
  await expect(page.getByRole("button", { name: /Export flags as JSON \(1\)/ })).toBeVisible();
});

test("[stubbed API] app still works when localStorage throws", async ({ page }) => {
  await page.addInitScript(() => {
    Object.defineProperty(window, "localStorage", {
      get() {
        throw new Error("SecurityError: storage disabled");
      },
    });
  });
  await page.goto("/");
  await stubDetect(page, { predictions: PREDICTIONS, image: { width: 1200, height: 800 }, malformedCount: 0 });
  await upload(page, "small.jpg");
  await page.getByRole("button", { name: "Analyse" }).click();
  await page.getByRole("button", { name: "Flag wrong result" }).click();
  await page.getByRole("button", { name: "Save flag" }).click();
  await expect(page.getByText(/Browser storage is unavailable/)).toBeVisible();
  await expect(page.getByRole("button", { name: /Export flags as JSON \(1\)/ })).toBeEnabled();
});

