test("[stubbed API] rate limit shows a retry button that works", async ({ page }) => {
  let calls = 0;
  await page.route("**/api/detect", async (route) => {
    calls += 1;
    if (calls === 1) {
      await route.fulfill({
        status: 429,
        contentType: "application/json",
        body: JSON.stringify({ error: { code: "RATE_LIMITED", message: "x" } }),
      });
    } else {
      await route.fulfill({
        status: 200,
        contentType: "application/json",
        body: JSON.stringify({ predictions: PREDICTIONS, image: { width: 1200, height: 800 }, malformedCount: 0 }),
      });
    }
  });
  await upload(page, "small.jpg");
  await page.getByRole("button", { name: "Analyse" }).click();
  await expect(page.getByTestId("error-box")).toContainText("too many requests");
  await page.getByRole("button", { name: "Try again" }).click();
  await expect(page.getByTestId("rating-summary")).toBeVisible();
  expect(calls).toBe(2);
});

