test("[stubbed API] large photos are resized to 1600 px and sent as JPEG under 4 MB", async ({ page }) => {
  let sent = "";
  await stubDetect(page, { predictions: [], image: null, malformedCount: 0 }, 200, (j) => (sent = j.image));
  await upload(page, "large-4000x3000.jpg");
  await page.getByRole("button", { name: "Analyse" }).click();
  await expect(page.getByTestId("rating-label")).toBeVisible();
  expect(await canvasSize(page)).toEqual({ w: 1600, h: 1200 });
  const jpeg = Buffer.from(sent, "base64");
  expect(jpeg[0]).toBe(0xff);
  expect(jpeg[1]).toBe(0xd8); // JPEG magic
  expect(sent.length).toBeLessThan(4_000_000);
});

test("[stubbed API] incompressible image still fits under the 4 MB request limit", async ({ page }) => {
  let sent = "";
  await stubDetect(page, { predictions: [], image: null, malformedCount: 0 }, 200, (j) => (sent = j.image));
  await upload(page, "noise-1800.png");
  await page.getByRole("button", { name: "Analyse" }).click();
  await expect(page.getByTestId("rating-label")).toBeVisible();
  const size = await canvasSize(page);
  expect(Math.max(size.w, size.h)).toBeLessThanOrEqual(1600);
  expect(JSON.stringify({ image: sent }).length).toBeLessThan(4_000_000);
});

